import pandas as pd
import numpy as np

class DataCleaning:
    def __init__(self):
        self.actions_log = []

    def clean(self, data: pd.DataFrame):
        data = data.copy()

        clip_rules = {
            "VehAge": 20,
            "DrivAge": 90,
            "BonusMalus": 150,
            "ClaimNb": 5
        }

        for col, upper_bound in clip_rules.items():
            if col in data.columns:
                data[col] = data[col].clip(upper=upper_bound)
                self.actions_log.append(f"Clipped {col} at upper={upper_bound}.")
            else:
                self.actions_log.append(f"Skipped clipping: {col} not found.")

        for col in ["VehPower", "Density", "MaxVehicleSpeed"]:
            if col in data.columns:
                mean_val = data[col].mean()
                std_val = data[col].std()
                data[col] = (data[col] - mean_val) / std_val
                self.actions_log.append(f"Standardized {col}.")

        for col in ["Area", "VehBrand", "VehGas", "Region"]:
            if col in data.columns:
                if col in ["Area", "VehBrand", "VehGas", "Region"]:
                    data[col] = data[col].astype("category").cat.codes + 1
                    self.actions_log.append(f"Mapped {col} categories to numeric scale.")
            else:
                self.actions_log.append(f"Skipped encoding: {col} not found.")

        data = pd.get_dummies(data, drop_first=True)
        self.actions_log.append("Converted categorical variables to dummy/indicator variables.")

        return data
